def parts(order)
  Enumerator.new do |y|
    order[:items].each_with_index do |item, i|
      y << { corr: order[:id], seq: i, size: order[:items].size, body: item }
    end
  end
end
parts(order).lazy.each { |part| bus.publish(part) }
